using System;using Newtonsoft.Json;using Newtonsoft.Json.Linq;public class CPHInline{
 static readonly object StateLock=String.Intern("streamercompanion:reactive-cameras:state:v1");
 const string K="portable.reactive.state";
 public bool Execute(){string mode=A("reactiveActionMode").ToLowerInvariant();if(mode=="assign-camera2"){if(!CPH.ActionExists("Cameras - Assign Reactive")){CPH.LogError("[reactive] Install Cameras before assigning Camera 2.");return true;}CPH.SetArgument("id",A("id"));return CPH.RunAction("Cameras - Assign Reactive",true);}bool result;lock(StateLock){result=ExecuteLocked();}if(result&&(mode=="save"||mode=="delete")&&CPH.ActionExists("Cameras - Sync Reactive"))CPH.RunAction("Cameras - Sync Reactive",true);return true;}
 bool ExecuteLocked(){try{string m=A("reactiveActionMode").ToLowerInvariant();if(m=="initialize")return InitializeState();if(m=="health")return Health();if(m=="configure")return Configure();if(m=="save")return SaveGuest();if(m=="toggle")return Toggle();if(m=="delete")return Delete();if(m=="move")return Move();if(m=="assign-camera2")return Assign();throw new Exception("Unknown mode: "+m);}catch(Exception e){try{W(State(),false,e.Message);}catch{}CPH.LogError("[reactive] "+e.Message);return false;}}
 JObject DefaultPresentation(){return new JObject{{"bottomOffsetPx",0},{"maxWidthPercent",48},{"avatarSizePx",180},{"gapPx",8}};}JObject Empty(){return new JObject{{"moduleVersion","2.1.0"},{"guests",new JArray()},{"camera2GuestId",""},{"presentation",DefaultPresentation()}};}JObject State(){string raw=Read();return raw==""?Empty():(JObject)JObject.Parse(raw)["payload"]??throw new Exception("Reactive state is invalid.");}
 bool InitializeState(){JObject s=State();s["moduleVersion"]="2.1.0";s["guests"]=s["guests"]??new JArray();s["camera2GuestId"]=s["camera2GuestId"]??"";s["presentation"]=NormalizePresentation(s["presentation"] as JObject??new JObject());return W(s);}bool Health(){JObject s=State();JArray g=s["guests"] as JArray;if(g==null)throw new Exception("Missing guests.");CPH.LogInfo("[reactive] Health OK: schema=2 module=2.1.0 guests="+g.Count+" active="+Active(g));return true;}
 bool Configure(){JObject s=State(),input=JObject.Parse(A("config"));if(input["presentation"]!=null)s["presentation"]=NormalizePresentation(input["presentation"] as JObject);return W(s);}JObject NormalizePresentation(JObject p){return new JObject{{"bottomOffsetPx",Clamp((int?)p["bottomOffsetPx"]??0,0,400)},{"maxWidthPercent",Clamp((int?)p["maxWidthPercent"]??48,10,100)},{"avatarSizePx",Clamp((int?)p["avatarSizePx"]??180,40,500)},{"gapPx",Clamp((int?)p["gapPx"]??8,0,80)}};}
 bool SaveGuest(){JObject s=State();JArray g=s["guests"] as JArray??new JArray();string id=A("id");if(id=="")id=Guid.NewGuid().ToString("N");string url=A("url");Uri u;if(!Uri.TryCreate(url,UriKind.Absolute,out u)||(u.Scheme!="http"&&u.Scheme!="https"))throw new Exception("Reactive URL must be http or https.");JObject n=new JObject{{"id",id},{"name",Limit(A("name"),80)},{"url",url},{"enabled",B("enabled",true)}};int at=-1;for(int i=0;i<g.Count;i++)if((string)g[i]["id"]==id){at=i;break;}if(at>=0)g[at]=n;else g.Add(n);s["guests"]=g;return W(s);}
 bool Toggle(){JObject s=State();foreach(JObject x in s["guests"] as JArray??new JArray())if((string)x["id"]==A("id"))x["enabled"]=B("enabled");return W(s);}bool Delete(){JObject s=State();JArray g=s["guests"] as JArray??new JArray();string id=A("id");for(int i=g.Count-1;i>=0;i--)if((string)g[i]["id"]==id)g.RemoveAt(i);if((string)s["camera2GuestId"]==id)s["camera2GuestId"]="";return W(s);}bool Move(){JObject s=State();JArray g=s["guests"] as JArray??new JArray();string id=A("id"),direction=A("direction");int at=-1;for(int i=0;i<g.Count;i++)if((string)g[i]["id"]==id){at=i;break;}int to=direction=="up"?at-1:direction=="down"?at+1:at;if(at>=0&&to>=0&&to<g.Count){JToken item=g[at];g.RemoveAt(at);g.Insert(to,item);}return W(s);}bool Assign(){JObject s=State();string id=A("id");if(id!=""&&!Has(s["guests"] as JArray,id))throw new Exception("Unknown guest.");s["camera2GuestId"]=id;return W(s);}
 bool Has(JArray g,string id){if(g!=null)foreach(JObject x in g)if((string)x["id"]==id)return true;return false;}int Active(JArray g){int n=0;foreach(JObject x in g)if((bool?)x["enabled"]??false)n++;return n;}int Clamp(int v,int a,int b){return Math.Max(a,Math.Min(b,v));}string Limit(string v,int n){v=(v??"").Trim();return v.Length<=n?v:v.Substring(0,n);}string A(string k){try{return args.ContainsKey(k)&&args[k]!=null?args[k].ToString().Trim():"";}catch{return"";}}bool B(string k,bool d=false){bool v;return Boolean.TryParse(A(k),out v)?v:d;}string Read(){try{return CPH.GetGlobalVar<string>(K,true)??"";}catch{return"";}}
 bool W(JObject p,bool success=true,string error=""){p["moduleVersion"]="2.1.0";p["lastOperation"]=new JObject{{"requestId",A("requestId")},{"status",success?"ok":"error"},{"error",error}};long r=1;try{r=((long?)JObject.Parse(Read())["revision"]??0)+1;}catch{}JObject e=new JObject{{"schemaVersion",1},{"feature","reactive"},{"type","state"},{"revision",r},{"payload",p}};string j=e.ToString(Formatting.None);CPH.SetGlobalVar(K,j,true);try{CPH.WebsocketBroadcastJson(j);}catch{}return true;}
}
